for filename in ('INBOUND_PROMPT.md', 'OUTBOUND_PROMPT.md'):
    path = Path('docs/prompts/shannmuga hospital') / filename
    before = path.read_text(encoding='utf-8')
    text = before
    if filename.startswith('INBOUND'):
        sections['Opening and returning callers'] = '''Skip welcome already played; else greet once: "வணக்கம்! Shanmuga Hospital AI assistant கார்த்திகா பேசுறேன். உங்களுக்கு என்ன details வேணும்?" Answer an already-stated need; no routine inbound convenience question or campaign/Facebook/booking assumptions.
Returning: establish speaker before private history; name/phone is not verification. Use only relevant verified history/pending questions, not completed tasks. Current need wins. Missed callback needs records; busy/failed call proves no missed callback. Help now if requested.
Inbound callback enquiry stays inbound, never claim an outbound callback: "சரி, இப்போ உங்களுக்கு உதவி பண்றேன்." Ask need only if unknown. New automated Karthika callback follows manage_follow_up, not human follow-up.'''
    else:
        sections['Opening and returning callers'] = '''Authorized contacts only. Skip played welcome; else identify once, verified reason and convenience: "வணக்கம்! Shanmuga Hospital AI assistant கார்த்திகா பேசுறேன். Health check-up packages பத்தி பேச call பண்ணிருக்கேன். இப்போ பேசலாமா?" Prior enquiry/Facebook only if verified; otherwise neutral reason. Yes/okay continues, not booking consent. Direct questions answered first, no repeated opening/permission.
Verified AI callback: "வணக்கம்! Shanmuga Hospital AI assistant கார்த்திகா பேசுறேன். நீங்க கேட்ட callbackக்காக call பண்ணிருக்கேன். இப்போ பேசலாமா?" Known name once if appropriate. Pending record alone proves no callback attempt; no invented interval/history/human callback claim.
Returning: establish speaker before private medical history, name/phone is not verification. General verified purpose until then; reuse relevant known details/pending step, not completed tasks/new sales. Current intent wins. Busy follows agreed AI callback; refusal/wrong number/no-further-calls closes without pressure.'''
    for heading, body in sections.items():
        pattern = r'(?m)^## ' + re.escape(heading) + r'\n.*?(?=^## |\Z)'
        text, count = re.subn(pattern, lambda _: '## ' + heading + '\n' + body + '\n\n', text, flags=re.S | re.M)
        assert count == 1, heading
    # All untouched sections, including openings, safety, callbacks and native transfer, remain byte-for-byte in normalized text.
    def blocks(s):
        return {m.group(1): m.group(2) for m in re.finditer(r'^## (.*?)\n(.*?)(?=^## |\Z)', s, re.M | re.S)}
    old, new = blocks(before), blocks(text)
    for heading in old:
        if heading not in sections:
            assert old[heading] == new[heading], heading
    assert re.findall(r'\{\{.*?\}\}', before) == re.findall(r'\{\{.*?\}\}', text)
    assert 'check_appointment_slots' not in text
    assert len(text.replace('\n', '\r\n')) < 15000, len(text)
    assert '\ufffd' not in text and '????' not in text
    path.write_text(text, encoding='utf-8')
    (Path('outputs/shanmuga-booking-prompts') / filename).write_text(text, encoding='utf-8')
    print(filename, 'LF characters:', len(text), 'CRLF characters:', len(text.replace('\n','\r\n')), 'unchanged sections and placeholders verified')
